import type{ProductStatus}from"../../types/vendor";export default function VendorProductStatusBadge({status}:{status:ProductStatus}){const tone=status==="ACTIVE"?"bg-green-100 text-green-800":status==="ARCHIVED"?"bg-slate-200 text-slate-700":"bg-amber-100 text-amber-800";return <span className={`rounded-full px-3 py-1 text-xs font-semibold ${tone}`}>{status.replaceAll("_"," ")}</span>}
